/**
 * A Frontier statistics publication is followed by an acknowledgement that prunes the mutation journal in an LMDB write
 * transaction of its own. That commit moves the physical snapshot epoch without changing a statement, so a rebuild that
 * finds only such commits between the published generation and its snapshot must treat the snapshot as covered: no
 * second build, no new generation, no Frontier planning-revision move.
 */
class LmdbFrontierAcknowledgementRebuildTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "urn:frontier-acknowledgement:";
	private static final IRI NAME = VF.createIRI(NS + "name");
	private static final IRI AGE = VF.createIRI(NS + "age");
	private static final IRI CATEGORY = VF.createIRI(NS + "category");
	private static final IRI KNOWS = VF.createIRI(NS + "knows");
	private static final int PEOPLE = 400;
	private static final long WAIT_SECONDS = 120L;

	@TempDir
	Path directory;

	@Test
	void theRequestedRebuildAfterAnExplicitRebuildPublishesNoSecondGeneration() throws Exception {
		try (Harness harness = new Harness(directory, false, true, false)) {
			harness.load();
			assertTrue(harness.baseReached.await(WAIT_SECONDS, TimeUnit.SECONDS),
					"COVERAGE_PREREQUISITE: the rebuild requested by the load committed to a base rebuild");

			FrontierStatisticsStatus explicit = harness.store.rebuildFrontierStatistics();
			long[] snapshot = harness.snapshotCoordinates();
			assertAll(
					() -> assertEquals(FrontierStatisticsAvailability.READY, explicit.availability()),
					() -> assertEquals(explicit.coveredSequence(), snapshot[1],
							"COVERAGE_PREREQUISITE: no statement changed after the explicit rebuild"),
					() -> assertTrue(snapshot[0] > explicit.coveredEpoch(),
							"COVERAGE_PREREQUISITE: the acknowledgement committed after the publication"));
			long revision = harness.frontierPlanningRevision();

			harness.baseReleased.countDown();
			assertTrue(harness.baseCompleted.await(WAIT_SECONDS, TimeUnit.SECONDS),
					"the requested base rebuild ran to completion");
			FrontierStatisticsStatus after = harness.backing().frontierStatisticsStatus();
			assertAll(
					() -> assertEquals(explicit.generationId(), after.generationId(),
							"the requested rebuild must not publish a second generation"),
					() -> assertEquals(explicit.coveredEpoch(), after.coveredEpoch()),
					() -> assertEquals(revision, harness.frontierPlanningRevision(),
							"the Frontier planning revision must not move without a statement change"),
					() -> assertEquals(-1L, after.buildEtaMillis(),
							"the service reports the requested rebuild as already covered, not as a completed build"),
					() -> assertEquals(0.0d, after.scanRate(), 0.0d,
							"the service reports no second statement pass"));
		}
	}

	@Test
	void aStatementCommitBetweenTheRebuildsStillRebuilds() throws Exception {
		try (Harness harness = new Harness(directory, false, true, false)) {
			harness.load();
			assertTrue(harness.baseReached.await(WAIT_SECONDS, TimeUnit.SECONDS),
					"COVERAGE_PREREQUISITE: the rebuild requested by the load committed to a base rebuild");
			FrontierStatisticsStatus explicit = harness.store.rebuildFrontierStatistics();
			assertEquals(FrontierStatisticsAvailability.READY, explicit.availability());

			harness.addOneStatement();
			harness.baseReleased.countDown();
			assertTrue(harness.baseCompleted.await(WAIT_SECONDS, TimeUnit.SECONDS),
					"the requested base rebuild ran to completion");
			FrontierStatisticsStatus after = harness.backing().frontierStatisticsStatus();
			assertAll(
					() -> assertTrue(after.generationId() > explicit.generationId(),
							"a statement commit after the publication requires a new generation"),
					() -> assertEquals(explicit.coveredSequence() + 1L, after.coveredSequence(),
							"the new generation covers the interleaved statement"));
		}
	}

	@Test
	void anExplicitRebuildAfterADeltaPublicationIsAlreadyCovered() throws Exception {
		try (Harness harness = new Harness(directory, true, false, false)) {
			harness.load();
			FrontierStatisticsStatus base = harness.store.rebuildFrontierStatistics();
			assertEquals(FrontierStatisticsAvailability.READY, base.availability());
			harness.addOneStatement();

			harness.runsAdmitted.countDown();
			assertTrue(harness.runsCompleted.tryAcquire(WAIT_SECONDS, TimeUnit.SECONDS),
					"the requested background refresh ran to completion");
			FrontierStatisticsStatus delta = harness.backing().frontierStatisticsStatus();
			long[] snapshot = harness.snapshotCoordinates();
			assertAll(
					() -> assertEquals(0, harness.baseEntries.get(),
							"COVERAGE_PREREQUISITE: the background refresh took the delta path"),
					() -> assertTrue(delta.generationId() > base.generationId(),
							"COVERAGE_PREREQUISITE: the delta was published"),
					() -> assertEquals(base.coveredSequence() + 1L, delta.coveredSequence()),
					() -> assertEquals(delta.coveredSequence(), snapshot[1]),
					() -> assertTrue(snapshot[0] > delta.coveredEpoch(),
							"COVERAGE_PREREQUISITE: the delta's acknowledgement committed after its publication"));
			long revision = harness.frontierPlanningRevision();

			FrontierStatisticsStatus explicit = harness.store.rebuildFrontierStatistics();
			assertAll(
					() -> assertEquals(delta.generationId(), explicit.generationId(),
							"an explicit rebuild of an unchanged store must not publish a new generation"),
					() -> assertEquals(delta.coveredEpoch(), explicit.coveredEpoch()),
					() -> assertEquals(revision, harness.frontierPlanningRevision(),
							"the Frontier planning revision must not move without a statement change"));
		}
	}

	@Test
	void anExplicitRebuildAfterTheOpeningAcknowledgementIsAlreadyCovered() throws Exception {
		long generation;
		long coveredEpoch;
		long coveredSequence;
		// The first session publishes a generation and stops before its acknowledgement commits.
		try (Harness first = new Harness(directory, true, false, true)) {
			first.load();
			FrontierStatisticsStatus published = first.store.rebuildFrontierStatistics();
			long[] snapshot = first.snapshotCoordinates();
			assertAll(
					() -> assertEquals(FrontierStatisticsAvailability.READY, published.availability()),
					() -> assertEquals(published.coveredSequence(), snapshot[1]),
					() -> assertEquals(published.coveredEpoch(), snapshot[0],
							"COVERAGE_PREREQUISITE: nothing committed after the publication"),
					() -> assertEquals(0L, first.journalState().acknowledgedThroughSequence(),
							"COVERAGE_PREREQUISITE: the publication was never acknowledged"));
			generation = published.generationId();
			coveredEpoch = published.coveredEpoch();
			coveredSequence = published.coveredSequence();
		}

		try (Harness second = new Harness(directory, true, false, false)) {
			assertTrue(second.backing().awaitFrontierStatisticsReady(TimeUnit.SECONDS.toMillis(WAIT_SECONDS)),
					"the reopened store published the persisted generation");
			FrontierStatisticsStatus opened = second.backing().frontierStatisticsStatus();
			long[] snapshot = second.snapshotCoordinates();
			assertAll(
					() -> assertEquals(generation, opened.generationId()),
					() -> assertEquals(coveredSequence, second.journalState().acknowledgedThroughSequence(),
							"COVERAGE_PREREQUISITE: opening acknowledged the published coverage"),
					() -> assertEquals(coveredSequence, snapshot[1]),
					() -> assertEquals(coveredEpoch + 1L, snapshot[0],
							"COVERAGE_PREREQUISITE: the opening acknowledgement is the only commit after the publication"));
			long revision = second.frontierPlanningRevision();

			FrontierStatisticsStatus explicit = second.store.rebuildFrontierStatistics();
			assertAll(
					() -> assertEquals(generation, explicit.generationId(),
							"an explicit rebuild of an unchanged store must not publish a new generation"),
					() -> assertEquals(coveredEpoch, explicit.coveredEpoch()),
					() -> assertEquals(revision, second.frontierPlanningRevision(),
							"the Frontier planning revision must not move without a statement change"));
		}
	}

	/**
	 * Owns a store whose background Frontier work the test sequences: scheduled refreshes can be held before they
	 * start, the base rebuild a scheduled refresh decided on can be held before it competes for the rebuild lock, and
	 * journal acknowledgements can fail as if the process stopped right after a publication.
	 */
	private static final class Harness implements AutoCloseable {
		final CountDownLatch runsAdmitted = new CountDownLatch(1);
		final Semaphore runsCompleted = new Semaphore(0);
		final CountDownLatch baseReached = new CountDownLatch(1);
		final CountDownLatch baseReleased = new CountDownLatch(1);
		final CountDownLatch baseCompleted = new CountDownLatch(1);
		final AtomicInteger baseEntries = new AtomicInteger();
		final LmdbStore store;
		private final SailRepository repository;

		Harness(Path directory, boolean holdRuns, boolean holdBase, boolean failAcknowledgements) {
			if (!holdRuns) {
				runsAdmitted.countDown();
			}
			if (!holdBase) {
				baseReleased.countDown();
			}
			LmdbStoreConfig config = new LmdbStoreConfig()
					.setBackgroundRawSamplingEnabled(false)
					.setOptimizerSamplingEnabled(false);
			store = new LmdbStore(directory.toFile(), config) {
				@Override
				LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig settings,
						boolean sketches) throws IOException, SailException {
					return new LmdbSailStore(dataDir, properties, settings, sketches, null,
							(tripleDir, tripleProperties, tripleSettings, values) -> new TripleStore(tripleDir,
									tripleProperties, tripleSettings, values) {
								@Override
								FrontierAcknowledgementCommit acknowledgeFrontierMutationsThrough(long coveredSequence,
										Txn reader) throws IOException {
									if (failAcknowledgements) {
										throw new IOException("Simulated stop before the Frontier acknowledgement");
									}
									return super.acknowledgeFrontierMutationsThrough(coveredSequence, reader);
								}
							}) {
						@Override
						void runScheduledFrontierRebuild() {
							await(runsAdmitted);
							try {
								super.runScheduledFrontierRebuild();
							} finally {
								runsCompleted.release();
							}
						}

						@Override
						boolean rebuildScheduledFrontierStatistics() {
							baseEntries.incrementAndGet();
							baseReached.countDown();
							await(baseReleased);
							try {
								return super.rebuildScheduledFrontierStatistics();
							} finally {
								baseCompleted.countDown();
							}
						}
					};
				}
			};
			repository = new SailRepository(store);
			repository.init();
		}

		LmdbSailStore backing() {
			return store.getBackingStore();
		}

		void load() {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				for (int index = 0; index < PEOPLE; index++) {
					IRI person = VF.createIRI(NS + "person/" + index);
					connection.add(person, NAME, VF.createLiteral("Person " + index));
					connection.add(person, AGE, VF.createLiteral(index % 100));
					connection.add(person, CATEGORY, VF.createLiteral("c" + index % 7));
					connection.add(person, KNOWS, VF.createIRI(NS + "person/" + (index + 1) % PEOPLE));
					connection.add(person, KNOWS, VF.createIRI(NS + "person/" + index * 7 % PEOPLE));
				}
				connection.commit();
			}
		}

		void addOneStatement() {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.add(VF.createIRI(NS + "person/late"), NAME, VF.createLiteral("Late"));
			}
		}

		long[] snapshotCoordinates() throws IOException {
			return backing().getTripleStore().snapshotCoordinates();
		}

		TripleStore.FrontierMutationJournalState journalState() throws IOException {
			return backing().getTripleStore().frontierMutationJournalState();
		}

		long frontierPlanningRevision() {
			return LmdbEstimatorRevisionSupport.frontierPlanningRevision(backing().frontierStatisticsStatus());
		}

		@Override
		public void close() {
			runsAdmitted.countDown();
			baseReleased.countDown();
			repository.shutDown();
		}

		private static void await(CountDownLatch latch) {
			try {
				if (!latch.await(WAIT_SECONDS, TimeUnit.SECONDS)) {
					throw new IllegalStateException("The test never released the held Frontier work");
				}
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				throw new IllegalStateException(interrupted);
			}
		}
	}
}
